import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    // handles potential non-digit if needed, but input is valid
                } else {
                    res = res * 10 + c - '0';
                }
                c = read();
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n <= 0) return;

        long[] x = new long[n];
        for (int i = 0; i < n; i++) {
            x[i] = scanner.nextInt();
        }

        long[] u = new long[n];
        long[] v = new long[n];
        long minU = Long.MAX_VALUE, maxU = Long.MIN_VALUE;
        long minV = Long.MAX_VALUE, maxV = Long.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            long y = scanner.nextInt();
            u[i] = x[i] + y;
            v[i] = x[i] - y;
            if (u[i] < minU) minU = u[i];
            if (u[i] > maxU) maxU = u[i];
            if (v[i] < minV) minV = v[i];
            if (v[i] > maxV) maxV = v[i];
        }

        if (n <= 2) {
            System.out.println(0);
            return;
        }

        long low = 0;
        long high = Math.max(maxU - minU, maxV - minV);
        long ans = high;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (check(n, u, v, minU, maxU, minV, maxV, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        System.out.println(ans);
    }

    private static boolean check(int n, long[] u, long[] v, long minU, long maxU, long minV, long maxV, long d) {
        // Configuration A:
        // Q1: [minU, minU + d] x [minV, minV + d]
        // Q2: [maxU - d, maxU] x [maxV - d, maxV]
        long limU1 = minU + d;
        long limV1 = minV + d;
        long limU2 = maxU - d;
        long limV2 = maxV - d;

        boolean okA = true;
        for (int i = 0; i < n; i++) {
            boolean inQ1 = (u[i] <= limU1 && v[i] <= limV1);
            boolean inQ2 = (u[i] >= limU2 && v[i] >= limV2);
            if (!inQ1 && !inQ2) {
                okA = false;
                break;
            }
        }
        if (okA) return true;

        // Configuration B:
        // Q1: [minU, minU + d] x [maxV - d, maxV]
        // Q2: [maxU - d, maxU] x [minV, minV + d]
        boolean okB = true;
        for (int i = 0; i < n; i++) {
            boolean inQ1 = (u[i] <= limU1 && v[i] >= limV2);
            boolean inQ2 = (u[i] >= limU2 && v[i] <= limV1);
            if (!inQ1 && !inQ2) {
                okB = false;
                break;
            }
        }
        return okB;
    }
